mapper.insert:
insert into sys_module_check (
  id, batch_id, module_code, module_name, status, latency_ms, message, checked_at
) values (
  #{id}, #{batchId}, #{moduleCode}, #{moduleName}, #{status}, #{latencyMs}, #{message}, #{checkedAt}
)

insert into sys_access_log (
  id, request_id, method, path, http_status, result_code, result_message,
  exception_type, duration_ms, username, created_at
) values (
  #{id}, #{requestId}, #{method}, #{path}, #{httpStatus}, #{resultCode}, #{resultMessage},
  #{exceptionType}, #{durationMs}, #{username}, #{createdAt}
)

mapper.sql:
where 1 = 1

  and (
    lower(path) like concat('%', lower(#{keyword}), '%')
    or lower(ifnull(username, '')) like concat('%', lower(#{keyword}), '%')
    or lower(request_id) like concat('%', lower(#{keyword}), '%')
    or lower(ifnull(result_message, '')) like concat('%', lower(#{keyword}), '%')
  )


  and method = #{method}


  and http_status = #{httpStatus}


  and result_code = #{resultCode}


  and created_at >= #{startDate}


  and created_at <= #{endDate}

mapper.delete:
delete from sys_access_log
where id in (
  select id from (
    select id from sys_access_log order by created_at asc limit #{limit}
  ) old_logs
)
